package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, k int64
	fmt.Fscan(reader, &n, &k)

	nn := n
	var ex int64 = 1

	for n%10 == 0 {
		n /= 10
		k--
	}
	for k > 0 {
		if n%2 == 0 {
			ex *= 5
			n /= 2
			k--
		} else if n%5 == 0 {
			ex *= 2
			n /= 5
			k--
		} else {
			break
		}
	}
	for k > 0 {
		ex *= 10
		k--
	}

	fmt.Fprintln(writer, ex*nn)
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	const maxBufSize = 1024 * 10
	buf := make([]byte, maxBufSize)
	scanner.Buffer(buf, maxBufSize)

	if !scanner.Scan() {
		return
	}
	n, _ := strconv.Atoi(scanner.Text())
	scanner.Scan()
	k, _ := strconv.Atoi(scanner.Text())

	nn := n
	ex := int64(1)

	for n%10 == 0 {
		n /= 10
		k--
	}
	for k > 0 {
		if n%2 == 0 {
			ex *= 5
			n /= 2
			k--
		} else if n%5 == 0 {
			ex *= 2
			n /= 5
			k--
		} else {
			break
		}
	}
	for k > 0 {
		ex *= 10
		k--
	}

	result := ex * int64(nn)
	writer := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(writer, result)
	writer.Flush()
}

